 <?php $__env->startSection('content'); ?>
<div class="page-head"><div><h1><?php echo e($product->exists?'Edit':'Add'); ?> Product</h1><p>SKU is generated by the server and stays stable.</p></div></div>
<form class="glass form-grid" method="post" enctype="multipart/form-data" action="<?php echo e($product->exists?route('products.update',$product):route('products.store')); ?>"><?php echo csrf_field(); ?> <?php if($product->exists): ?> <?php echo method_field('PUT'); ?> <?php endif; ?>
<div class="image-upload"><div id="preview"><?php if($product->image): ?><img src="<?php echo e(Storage::url($product->image)); ?>"><?php else: ?><span>📦<br>No Image</span><?php endif; ?></div><label>Product image<input id="image" type="file" name="image" accept=".jpg,.jpeg,.png,.webp" onchange="previewImage(this)"></label><small>JPG/JPEG/PNG/WebP, max 4MB</small></div>
<div class="fields"><label>Name<input name="name" value="<?php echo e(old('name',$product->name)); ?>" required></label><label>SKU<input value="<?php echo e($product->sku?:'Auto generated on save'); ?>" readonly></label><label>Category<select name="category_id"><option value="">None</option><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($c->id); ?>" <?php if(old('category_id',$product->category_id)==$c->id): echo 'selected'; endif; ?>><?php echo e($c->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Brand<select name="brand_id"><option value="">None</option><?php $__currentLoopData = $brands; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $b): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($b->id); ?>" <?php if(old('brand_id',$product->brand_id)==$b->id): echo 'selected'; endif; ?>><?php echo e($b->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Unit<input name="unit" value="<?php echo e(old('unit',$product->unit?:'pcs')); ?>" required></label><label>Purchase price<input type="number" step=".01" name="purchase_price" value="<?php echo e(old('purchase_price',$product->purchase_price)); ?>" required></label><label>Selling price<input type="number" step=".01" name="selling_price" value="<?php echo e(old('selling_price',$product->selling_price)); ?>" required></label><label>Wholesale price<input type="number" step=".01" name="wholesale_price" value="<?php echo e(old('wholesale_price',$product->wholesale_price)); ?>"></label><?php if (! ($product->exists)): ?><label>Opening stock<input type="number" step=".001" name="current_stock" value="<?php echo e(old('current_stock',0)); ?>"></label><?php endif; ?><label>Minimum stock<input type="number" step=".001" name="minimum_stock" value="<?php echo e(old('minimum_stock',$product->minimum_stock)); ?>"></label><label>Status<select name="status"><option value="active" <?php if(old('status',$product->status)=='active'): echo 'selected'; endif; ?>>Active</option><option value="inactive" <?php if(old('status',$product->status)=='inactive'): echo 'selected'; endif; ?>>Inactive</option></select></label><label class="full">Description<textarea name="description"><?php echo e(old('description',$product->description)); ?></textarea></label><button class="primary full">Save Product</button></div></form>
<?php $__env->stopSection(); ?>

